 assert.throws(()=>assertReservedResponseSourceBindings(raw,bad),error=>{failure=error.message;return error.code==='ERR_ASSERTION'&&error.message.startsWith(oracle);},'RESERVED_REFERENCE_FALSE_ATTRIBUTION_ORACLE');
 assert.equal(JSON.stringify(raw),rawBefore,'RESERVED_REFERENCE_RAW_UNCHANGED_ORACLE');assert.equal(JSON.stringify(proposal),proposalBefore,'RESERVED_REFERENCE_VALID_PROPOSAL_UNCHANGED_ORACLE');
