 assert.equal(raw.sha256,digest(raw.completeRawResponse),'EVIDENCE_EXTRACTION_RAW_DIGEST_ORACLE');
 assert.equal(manifest.rawResponseId,raw.rawResponseId,'EVIDENCE_EXTRACTION_RAW_ID_ORACLE');
